use vstd::prelude::*;

verus! {
    // Specification for squaring an integer
    spec fn square(x: i32) -> i32
        requires
            x * x < i32::MAX,
    {
        x * x
    }

    // Function to square each element in the input array
    fn square_nums(nums: &Vec<i32>) -> (squared: Vec<i32>)
        requires
            forall|i: nat| (i < nums.len() as nat) ==> (nums[i] * nums[i] < i32::MAX),
        ensures
            squared.len() == nums.len(),
            forall|i: nat| (i < nums.len() as nat) ==> (squared[i] == square(nums[i])),
    {
        let mut squared: Vec<i32> = Vec::new();
        let len = nums.len() as nat;

        // Initialize the output vector with the same length
        squared.reserve(len);

        let mut i: nat = 0;
        while i < len
            invariant
                i <= len,
                squared.len() == i,
                forall|j: nat| (j < i) ==> (squared[j] == square(nums[j])),
            decreases len - i,
        {
            // Get the current number to square
            let current_num = nums[i as usize];

            // Assert that squaring the current number is safe
            assert(current_num * current_num < i32::MAX);

            // Push the square of the current number to the output vector
            squared.push(square(current_num));

            // Increment the index
            i = i + 1;
        }

        squared
    }
}

